window.__saqPaperQuestions("2021-2-pah",[{"number":1,"title":"","stemText":"The ambulance service has notified you of the imminent arrival of a 25 year old man who has been stabbed once to the epigastrium with a large knife. His blood pressure is 75/50mmHg in the field.","parts":[{"id":"a","label":"Part A","prompt":"List 4 interventions you will prepare to perform. For each, state the clinical indication. (4 marks) Intervention Clinical indication A chest x-ray has been taken on arrival. It is shown below."},{"id":"b","label":"Part B","prompt":"State your conclusion, with 3 supporting radiographic abnormalities. (4 marks) Conclusion Supporting radiographic abnormalities 1) 2) 3) No other injuries have been identified on assessment. The patient has the following vital signs:\n\nGCS\nE3 V4 M6 agitated and unco-operative Pulse 140 /min\n\nBP\n70/40 mmHg\n\nRR\n/min O2 sats 99% 15L O2 via non-rebreather mask"},{"id":"c","label":"Part C","prompt":"State 4 components of your management of this patient. (4 marks)\n1) 2) 3) 4)"}],"propPages":["asset:img007a25fe5daa51e88b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Intercostal catheter insertion</strong> – signs of tension pneumothorax or massive haemothorax i.e.</td><td>evidence of PTX + hypotension/ hypoxia/ tachycardia/ marked resp distress /tachypnoea etc</td></tr><tr><td>Blood transfusion (accept massive transfusion) – ongoing specific numbers (SBP &lt;80 or end-organ</td><td>dysfunction, hypotension in ED)</td></tr><tr><td>Intubation – refractory hypoxia, agitation, cardiac arrest, to facilitate ICC or other painful procedures</td><td>Thoracotomy – cardiac arrest with pericardial effusion on EFAST</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Large hyperdense rim around entire L thorax</div><div class=\"answer-line\">Mediastinal shift to Rt</div><div class=\"answer-line\">Veiling across L hemithorax on supine film</div><div class=\"answer-line\">may be others...</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Intubation</div><div class=\"answer-line\">Left sided large bore ICC insertion</div><div class=\"answer-line\">Blood transfusion following Massive Transfusion protocol guidelines to mitigate coagulopathy</div><div class=\"answer-line\">Need to define 4th – TXA/Cardiothoracics</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 2 year old boy has been taken to triage by his parents who found the child playing with an open box of his grandfather’s metoprolol tablets.","parts":[{"id":"a","label":"Part A","prompt":"State 4 aspects of your history pertaining to risk assessment. Explain the relevance of\neach. (4 marks) 1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"List 3 findings that would indicate established toxicity. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 5 potential treatments for this child. Give the clinical indication for each. (5 marks) Treatment Clinical indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Type of medication - immediate vs slow release – will impact risk assessment and time to toxicity</div><div class=\"answer-line\">Dose Ingested (maximum from number of missing tablets) – allows determination of potential</div><div class=\"answer-line\">toxicity</div><div class=\"answer-line\">Time of ingestion – predicts onset of toxicity and time for observation</div><div class=\"answer-line\">Events since – vomiting, LOC, treatments provided to date</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Altered Level of Consciousness</div><div class=\"answer-line\">PR prolongation</div><div class=\"answer-line\">Bronchospasm/Pulmonary Oedema</div><div class=\"answer-line\">hypoglycaemia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Charcoal – ingestion &lt;2hrs</td><td>IV fluid – hypotension without marked bradycardia</td></tr><tr><td>Chronotropy i.e. IV Atropine – symptomatic bradycardia (w hypotension)</td><td>Adrenaline/Isoprenaline Infusion – ongoing bradycardia (*only one of Atrop/Adren)</td></tr><tr><td>HIET – hypotension resistant to above measures</td><td>Intubation – altered consciousness/respiratory acidosis/vomiting and aspiration</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 23 year old woman has presented with a painful right eye.\nA photograph of the eye is given below.","parts":[{"id":"a","label":"Part A","prompt":"State the likely diagnosis with 3 supportive findings. (4 marks) Likely diagnosis Supportive findings 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 2 medical conditions associated with this pathology. (2 marks)\n1) 2)"},{"id":"c","label":"Part C","prompt":"List 3 further key aspects of your examination. (3 marks)\n1) 2) 3)"},{"id":"d","label":"Part D","prompt":"List 3 medications you would use to manage this patent. (3 marks)\n1) 2) 3)"}],"propPages":["asset:img21746293335d40eb65"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Iritis / Anterior uveitis</div><div class=\"answer-line\">Scleral injection</div><div class=\"answer-line\">Hypopion</div><div class=\"answer-line\">Irregular pupil suggestive of synechiae</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Inflammatory arthropathies</div><div class=\"answer-line\">Inflammatory bowel disease</div><div class=\"answer-line\">Others</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Visual acuity</div><div class=\"answer-line\">Intraocular pressure</div><div class=\"answer-line\">Pupil reactivity</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Mydriatics (atropine, tropicamide)</div><div class=\"answer-line\">Steroid drops</div><div class=\"answer-line\">Analgesia e.g. endone 5-10mg PO</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"You are alerted to an acute cubicle where a nurse has found a patient unresponsive and not breathing. The patient was sent down from the renal clinic after presenting with vomiting and lethargy. She has a history of end-stage renal failure due to type 1 diabetes mellitus. A trace from the cardiac monitoring is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the likely diagnosis, including 2 supportive features from the cardiac monitoring trace. (3 marks) Likely diagnosis Supportive features 1) 2) There is no palpable pulse."},{"id":"b","label":"Part B","prompt":"State 3 standard ALS measures you would institute. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"State 5 specific measures you would institute to manage the likely cause. Provide end-\npoints where appropriate. (5 marks) 1) 2) 3) 4) 5) After 20 minutes of CPR, you have been unable to achieve a return of spontaneous circulation."},{"id":"d","label":"Part D","prompt":"List 5 factors you will consider when determining whether to terminate resuscitative\nmeasures. (5 marks) 1) 2) 3) 4) 5)"}],"propPages":["asset:img09bbe0c88565f6f712"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Very wide QRS</div><div class=\"answer-line\">Tall t-waves (relative to QRS) with almost sine-wave appearance</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Commence external compressions 100/min</div><div class=\"answer-line\">External BVM ventilation, 2 breaths every 15 seconds (synchronised to 30:2 with compressions)</div><div class=\"answer-line\">IV adrenaline 1mg bolus</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>IV Calcium –</strong> (any formulation ok) repeated to achieve narrow QRS &lt;120ms or similar</div><div class=\"answer-line\">IV Na Bicarbonate to shift K intracellularly – 100mmol boluses, either with K goal of &lt;6 or pH limit of</div><div class=\"answer-line\">7.5</div><div class=\"answer-line\">IV insulin 10u as bolus, with 50mls 50% dextrose if BSL &lt;15 – goal K &lt;6</div><div class=\"answer-line\">Salbutamol via nebulised route if possible (10mg) or IV 5mcg/kg bolus up to 250mcg – goal K &lt;6</div><div class=\"answer-line\">Intubate to hyperventilate – pH 7.5</div><div class=\"answer-line\">Consulting ICU service to facilitate urgent inpatient dialysis once ROSCE achieved</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Presence of irreversible pathology i.e. refractory hyperK or refractory acidosis despite administered</div><div class=\"answer-line\">therapies</div><div class=\"answer-line\">Pre-existing QOL and functional status</div><div class=\"answer-line\">Previously expressed/documented wishes regarding ceiling of care</div><div class=\"answer-line\">Presence of cardiac activity on POCUS</div><div class=\"answer-line\">Presence of life-limiting comorbidities with limited life expectancy ie metastatic cancer, dementia</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 65 year old man has presented with severe central chest pain radiating through to his back. You are concerned about the diagnosis of thoracic aortic dissection.","parts":[{"id":"a","label":"Part A","prompt":"List 4 findings on examination that would favour a diagnosis of aortic dissection over acute coronary syndrome. (4 marks) 1) 2) 3) 4) Stanford type A aortic dissection has been confirmed on imaging. Further history has revealed that the patient is taking rivaroxaban for paroxysmal atrial fibrillation. The patient has the following vital signs:\n\nGCS\nPulse 100 /min\n\nBP\n170/100 mmHg O2 sats 99% room air"},{"id":"b","label":"Part B","prompt":"List 6 components of your management, including end-points where appropriate.\n(6 marks) 1) 2) 3) 4) 5) 6) While waiting for definitive management, the patient has developed hypotension at 70/40 mmHg."},{"id":"c","label":"Part C","prompt":"List 4 potential causes for the hypotension. For each, state the assessment finding\n(history, examination or investigation) that will confirm its presence. (8 marks) Cause Assessment finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Pulse deficit or BP differential</div><div class=\"answer-line\">Aortic regurgitation murmur (diastolic rumble)</div><div class=\"answer-line\">Focal Neurologic deficits</div><div class=\"answer-line\">Hypotension without signs pulmonary oedema</div><div class=\"answer-line\">Signs of pericardial effusion – muffled heart sounds, elevated JVP</div><div class=\"answer-line\">Morphologic features of Marfan Syndrome</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Analgesia – fentanyl 50mcg titrated to comfort</div><div class=\"answer-line\"><strong>Metoprolol IV (or equivalent) – 5mg repeat to HR &lt;60 </strong></div><div class=\"answer-line\">Once beta-blocked, GTN or hydralazine titrated to BP &lt;120mmHg</div><div class=\"answer-line\"><strong>Cardiothoracics attendance for definitive management in theatre </strong></div><div class=\"answer-line\">Rivaroxaban reversal with Prothrombin Complex Concentrate 50u/kg</div><div class=\"answer-line\">Tranexamic Acid 1gm IV bolus + infusion over 8hrs to mitigate fibrinolysis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Excess medication (Iatrogenic) – other causes excluded</td><td>Aortic rupture – haemothorax on CXR/EFAST</td></tr><tr><td><strong>Acute pericardial tamponade – large effusion on EFAST </strong></td><td>Acute MI from aortic root involvement – STEMI on ECG</td></tr><tr><td>Acute severe AR with pump failure – murmur with pulmonary congestion and empty pericardium OR</td><td>ECHO</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"You have been called to your short stay unit to a 12 year old girl who is complaining of difficulty breathing and a rash following the initiation of an intravenous infusion of penicillin. She was admitted to the short stay unit for management of tonsillitis. Your initial assessment suggests anaphylaxis.","parts":[{"id":"a","label":"Part A","prompt":"State 8 components of management you might initiate. Include the clinical indication or\nrationale for each. (8 marks) 1) 2) 3) 4) 5) 6) 7) 8) Your initial management has been successful."},{"id":"b","label":"Part B","prompt":"List 3 requirements for discharge. (3 marks)\n1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cessation of infusion if still running – to decrease allergen load</td><td><strong>IM adrenaline 0.3mg (accept 0.5mg as is on upper limit of age range) – for anaphylaxis </strong></td></tr><tr><td>IV adrenaline infusion 0.1-1mcg/kg/min – refractory hypotension despite IM adrenaline</td><td>IV antihistamines – if significant urticarial component</td></tr><tr><td>IV steroids – IV dexamethasone 0.15mg/kg for Anaphylaxis to decrease recurrence (will also help</td><td>tonsilitis)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Clinical</div><div class=\"answer-line\">Remains well for period of time (accept almost anything reasonable)</div><div class=\"answer-line\">Underlying condition managed to the point that outpatient management reasonable i.e.</div><div class=\"answer-line\">tolerating oral diet, pain under control, has discharge instructions re Abx</div><div class=\"answer-line\">Anaphylaxis Rx</div><div class=\"answer-line\">Clear understanding of allergy and NEVER for penicillin agents</div><div class=\"answer-line\">Script for 3 days of steroid at appropriate dose</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"Your director has asked you to meet with one of the resident medical officers. She has taken numerous sick days during the term without clear explanation.","parts":[{"id":"a","label":"Part A","prompt":"State 4 key features of your meeting with this junior doctor. (4 marks)\n1) 2) 3) 4) During your discussion, the junior doctor informs you that she has been self-medicating with alcohol to overcome workplace anxiety."},{"id":"b","label":"Part B","prompt":"State 4 findings on an alcohol history (other than absenteeism) that would be concerning\nfor problem drinking. (4 marks) 1) 2) 3) 4) Your conversation reveals a serious alcohol problem, including drinking at work."},{"id":"c","label":"Part C","prompt":"List 4 actions you will undertake to address this situation. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Off the floor away from clinical environment</div><div class=\"answer-line\">Establish confidential terms of meeting</div><div class=\"answer-line\">Explore understanding to establish RMO understanding of situation</div><div class=\"answer-line\">Explore factors contributing to excess sick leave – personal and professional</div><div class=\"answer-line\">Explain expectations of employment and use of personal/sick leave</div><div class=\"answer-line\">Others</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Drinking before work</div><div class=\"answer-line\">Drinking at work</div><div class=\"answer-line\">Drinking to enebriation “blacking out”</div><div class=\"answer-line\">Impairment of daily activities</div><div class=\"answer-line\">Prior problems with excess drinking</div><div class=\"answer-line\">CAGE questions – unable to cut down, anger around drinking, guilt around drinking</div><div class=\"answer-line\">Loss of memory of events</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Referral to EAS or equivalent for employee assistance</div><div class=\"answer-line\">Encourage engagement with GP, psychologist</div><div class=\"answer-line\">Stand-down from clinical duties until situation under control</div><div class=\"answer-line\">Referral to Alcohol and Drug Services or equivalent</div><div class=\"answer-line\">There will be others...</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 45 year old woman has been referred by her GP with the following blood results:\nTSH <0.05 mU/L (0.3 - 4.5) Free T4 pmol/L (7 - 17)","parts":[{"id":"a","label":"Part A","prompt":"Interpret the results. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 4 symptoms from 4 different systems that would be consistent with the above results.\n(4 marks) 1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List 4 examination findings from 4 different systems for which you would look. (4 marks)\n1) 2) 3) 4) Your assessment is consistent with thyroid storm."},{"id":"d","label":"Part D","prompt":"List 3 medications you would use. Include the relevant mechanism of action for each.\n(3 marks) 1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Primary hyperthyroidism</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Neuropsychiatric – anxiety, restlessness, agitation</div><div class=\"answer-line\">Cardiovascular – dyspnoea, palpitations</div><div class=\"answer-line\">Metabolic – weight loss, increased appetite</div><div class=\"answer-line\">Neuromuscular – tremor, shakes</div><div class=\"answer-line\">Cutaneous – diaphoresis, heat intolerance</div><div class=\"answer-line\">Gastrointestinal – hyperstooling</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Cutaneous – pretibial myxoedema, thyroid acropachy, Onycholysis</div><div class=\"answer-line\">CVS – tremor, tachycardia</div><div class=\"answer-line\">Neurologic – hyperreflexia</div><div class=\"answer-line\">Ocular – exophthalmus</div><div class=\"answer-line\">Thyroid – tender, enlarged gland, focal pathology (nodule, tumour)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Hydrocortisone IV 100mg TDS (prevents T4--&gt; T3)</td><td>Propothiouracil 50-300mg PO q8H – decreases gland activity and T4 conversion to T3</td></tr><tr><td>(preferred over Carbimazole 20mg)</td><td>Propranolol PO 10-40mg – decreases T4--&gt; T3, also decreases adrenergic effects of T3</td></tr><tr><td>Lugol’s Iodine 0.5ml TDS (blocks release of T hormone)</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 27 year old woman has presented with lower abdominal pain and fever. You are considering the diagnosis of pelvic inflammatory disease (PID).","parts":[{"id":"a","label":"Part A","prompt":"List 4 historical findings that would increase the likelihood of PID. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"List 4 investigations you might perform. Include your rationale. (4 marks)\n1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List 3 potential complications of PID other than sepsis and pain. (3 marks)\n1) 2) 3)\nPAH 2021.2 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Dyspareunia</div><div class=\"answer-line\">Vaginal discharge</div><div class=\"answer-line\">Prior PID</div><div class=\"answer-line\">Recent instrumentation</div><div class=\"answer-line\">Presence of IUD</div><div class=\"answer-line\">Unprotected sex</div><div class=\"answer-line\">Multiple partners</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">B-hCG – exclude pregnancy as differential +/- guide therapy</div><div class=\"answer-line\">High-Vaginal/ Endocervical swabs – determine organism</div><div class=\"answer-line\">Urine – first pass PCR for Chlamydial, Gonococcal PCR</div><div class=\"answer-line\">Syphilis serology</div><div class=\"answer-line\">Ultrasound – identify tubo-ovarian abscess</div><div class=\"answer-line\">Inflammatory markers if well justified ie CRP to guide response to therapy for non-surgical PID</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Tubo-ovarian abscess</div><div class=\"answer-line\">Scarring with fertility complications (accept ectopic risk OR infertility)</div><div class=\"answer-line\">Transmission of infection to sexual partners</div><div class=\"answer-line\">Chronic Pelvic pain</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 65 year old woman has presented with an isolated left wrist injury after tripping over a garden hose at home. AP and lateral x-rays are provided below.","parts":[{"id":"a","label":"Part A","prompt":"Describe the injury shown. (5 marks) You have elected to reduce the above injury under regional anaesthesia."},{"id":"b","label":"Part B","prompt":"List 3 contra-indications to the use of a Bier’s block. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"State 5 safety measures, with explanation, you will undertake in the safe performance of a Bier’s block. (5 marks) 1) 2) 3) 4) 5)"},{"id":"d","label":"Part D","prompt":"List 2 radiographical measurements that would signify an adequate reduction of this\ninjury. (2 marks) 1) 2) Shortly after application of a plaster cast, the patient has a generalised seizure. The patient’s vital signs are: Pulse 100 /min\n\nBP\n85/45 mmHg O2 sats 100% 6L O2 via Hudson mask"},{"id":"e","label":"Part E","prompt":"State 4 components of your management, including end-points where appropriate.\n(4 marks) 1) 2) 3) 4) The patient recovers without incident. On review you note the anaesthetic was infiltrated before the cuff was checked, and that the cuff is not working effectively."},{"id":"f","label":"Part F","prompt":"List 5 aspects of your response to this incident. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":["asset:imge0522dea8c79e2a357"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left distal radial fracture</div><div class=\"answer-line\">Comminution</div><div class=\"answer-line\">Approx 5mm impaction</div><div class=\"answer-line\">Dorsal angulation approx. 15 deg</div><div class=\"answer-line\">Dorsal displacement approx. 20%</div><div class=\"answer-line\">Intraarticular extension</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Local Anaesthetic allergy</div><div class=\"answer-line\">Open Fracture</div><div class=\"answer-line\">Sickle cell disease</div><div class=\"answer-line\">Severe Hypertension i.e. Systolic &gt;180mmHg</div><div class=\"answer-line\">Others</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Contralateral IV access – in case of need for rescue meds, additional analgesia</div><div class=\"answer-line\">3-lead cardiac monitoring – identification of arrhythmia as sign of LA toxicity</div><div class=\"answer-line\">Double cuff pneumatic tourniquet – allows for single cuff failure without systemic LA exposure</div><div class=\"answer-line\">LA dosing guided by toxicity limits – systemic leak less likely to produce toxicity</div><div class=\"answer-line\">Pulse check once cuff applied to ensure efficacy</div><div class=\"answer-line\">Performance in resus-capable room with dedicated nursing staff in case of complications</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Anatomical angulation ie 11deg volar</div><div class=\"answer-line\">Anatomical radial length ie &gt;4mm distal to ulna</div><div class=\"answer-line\">Radial Inclination – normal 23deg</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Midazolam 5mg IV to seizure termination</div><div class=\"answer-line\">NaHCO3 100mmol IV for Na Blockade antagonism</div><div class=\"answer-line\">IV crystalloid 20mg/kg +/- inotropic support for significant hypotension – aiming SBP&gt;90</div><div class=\"answer-line\">IV intralipid</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Open Disclosure to patient</div><div class=\"answer-line\">Clear documentation of events</div><div class=\"answer-line\">M&amp;M referral of case for review</div><div class=\"answer-line\">Remove equipment from workplace – notify equipment team for equipment/service audit and</div><div class=\"answer-line\">repair</div><div class=\"answer-line\">Review Bier’s block process to ensure adequate safety checks built into procedure to prevent</div><div class=\"answer-line\">recurrence</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 45 year old woman has been brought to the ED after being extricated from a house fire.\nShe has sustained significant burns.","parts":[{"id":"a","label":"Part A","prompt":"List 3 characteristic features of deep thickness burns. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"State 2 methods of calculating the percentage area of burns. (2 marks)\n1) 2)"},{"id":"c","label":"Part C","prompt":"State your intended plan for fluid management in the first 24hrs of the patient’s hospitalisation. (2 marks) The patient was exposed to a significant amount of smoke while trapped inside the house."},{"id":"d","label":"Part D","prompt":"List 4 possible complications from this, including how you will assess for the presence of each. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Involves entire epidermis and dermis</div><div class=\"answer-line\">Non-blanching/no cap refil</div><div class=\"answer-line\">Charred, pale, leathery</div><div class=\"answer-line\">Painless</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Rule of nines</div><div class=\"answer-line\">Lund &amp; Browder diagram</div><div class=\"answer-line\">Area of back of patient’s hand = 1% BSA</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Parkland formula – 4mls/kg x % BSA = ½ in first 8 hours from time of injury, ½ in next 16 hours</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Upper airway burns – visible airway oedema, stridor</div><div class=\"answer-line\">Pneumonitis/inhalational lung injury – bronchospasm, carbonaceous sputum, soot in mouth, facial</div><div class=\"answer-line\">burns</div><div class=\"answer-line\">Carbon monoxide poisoning – cns signs, elevated carboxyhaemoglobin level</div><div class=\"answer-line\">Cyanide toxicity – lactate &gt;10 without severe burns</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 3 week old boy has been brought to the ED with vomiting.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses. For each, state a cardinal feature of the history that would support the diagnosis. (8 marks) Diagnosis Cardinal historical feature A venous blood gas has been taken. The result is given below. Venous blood gas\n\npH\n7.618 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\npO2\nmmHg\n\nHCO3\nmmol/L (21 - 28)\n\nNa\n136 mmol/L (134 - 146)\n\nK\n3.0 mmol/L (3.4 - 5.0)\n\nCl\nmmol/L (98 - 108)"},{"id":"b","label":"Part B","prompt":"State 3 abnormalities demonstrated. Include the cause of each. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"State the most likely diagnosis. (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Sepsis – fevers</td><td>Pyloric stenosis – projectile vomits, non-bilious</td></tr><tr><td>Biliary pathology ie atresia – worsening jaundice, bilious vomiting</td><td>Incarcerated hernia with obstruction – observed mass by parents in groin/peri-umbilical  region</td></tr><tr><td>Meningitis/raised ICP – inconsolability, witnessed posturing</td><td>Hirschprungs – no bowel motions</td></tr><tr><td>Necrotising Enterocolitis – haematochezia, abdominal distention, Hx prematurity</td><td>There will be others</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Marked metabolic alkalosis – H+ loss in vomit</div><div class=\"answer-line\">Compensatory respiratory acidosis – expected CO2 = 0.7 x 56 + 20 = 58)</div><div class=\"answer-line\">Hypokalaemia from pH associated shift into cells (H+ shift into cells) + also possible component of</div><div class=\"answer-line\">loss in vomiting</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Pyloric Stenosis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 75 year old man has presented with progressive dyspnoea for the last 12 hours. He is known to have advanced COPD.","parts":[{"id":"a","label":"Part A","prompt":"List 4 medications, including doses, you might use for the management of this patient in\nthe ED. Provide a clinical indication and rationale for each. (4 marks) 1) 2) 3) 4) After reviewing the patient, an ABG is performed. The result is provided below. Arterial blood gas (6L oxygen via Hudson mask)\n\npH\n7.23 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\npO2\n100 mmHg (>60)\n\nHCO3\nmmol/L (21 - 28)"},{"id":"b","label":"Part B","prompt":"State your interpretation of the patient’s ABG including relevant explanation. (3 marks) You have elected to commence non-invasive ventilation (NIV) as part of your management."},{"id":"c","label":"Part C","prompt":"List 4 end-points you will use to determine the effectiveness of your NIV therapy.\n(4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Medication</th><th>Justification</th></tr></thead><tbody><tr><td><strong>B-agonist ie salbutamol</strong> – bronchodilator, history of reversible component to airways disease on</td><td>lung function testing or anecdotal improvement with prior treatment</td></tr><tr><td>Anticholinergic ie ipratropium – prevention of bronchospasm and decreased secrections to decrease</td><td>airflow resistance and mucous plugging – use if increased work of breathing or wheeze</td></tr><tr><td>Oxygen – if demonstrable hypoxia below patient’s baseline or evidence of respiratory distress</td><td>(tachypnoea/air hunger)</td></tr><tr><td>Glucocorticoids ie prednisolone – decreased inflammation/oedema/mucous production in</td><td>obstructive lung disease.  Indicated if global wheeze evident on exam (accept marked prolongation</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Acute on Chronic Respiratory Acidosis (Type II Resp Failure)</div><div class=\"answer-line\">High CO2/low pH confirms resp acidosis</div><div class=\"answer-line\">Degree of acidaemia and elevation of bicarbonate indicates chronicity</div><div class=\"answer-line\">pH lower than would be entirely explained by all chronic changes</div><div class=\"answer-line\">Relative Hypoxia for FiO2<span class=\"answer-source-red\"> </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Patient’s perceived breathlessness</div><div class=\"answer-line\">Patient’s respiratory work and resp rate</div><div class=\"answer-line\">Tidal volumes/minute ventilation from machine feedback</div><div class=\"answer-line\">Blood gas evidence of decrementing CO2, incrementing pH</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 65 year old female has presented to the Emergency Department after a syncopal event at home. Her arrival ECG is reproduced below.","parts":[{"id":"a","label":"Part A","prompt":"State the main pathology demonstrated, with 3 supporting ECG abnormalities. (4 marks) Main pathology Supporting ECG abnormalities 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 possible reversible causes for this problem, including a historical feature that would make that cause more likely. (6 marks) Reversible Cause Historical feature The patient has hypotension with poor systemic perfusion."},{"id":"c","label":"Part C","prompt":"List 2 medications you could infuse to manage this pathology. For each, state a rationale\nfor its preferential use. (2 marks) 1) 2)"}],"propPages":["asset:img44279e625fb5e5a57d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">AV dissociation (3rd degree AV or Heart block) with junctional escape</div><div class=\"answer-line\">Regular P waves, rate approx. 80/min</div><div class=\"answer-line\">Regular QRS complexes, rate approx. 35-40bpm</div><div class=\"answer-line\">No P-QRS relationship</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ischaemia ie RCA occlusion – history of ischaemic chest pain or known prior IHD</div><div class=\"answer-line\">Hyperkalaemia – Hx Renal disease or recent volume losses</div><div class=\"answer-line\">Medications – History AV blocking agents ie non-dihidropyridines (Verapamil, diltiazem), digoxin etc</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Medication</th><th>Justification</th></tr></thead><tbody><tr><td>Isoprenaline – B1 agonist – where rate thought to be primary issue</td><td>(could also be adrenaline)</td></tr><tr><td>Dobutamine – where pump dysfunction a significant concern (could also use adrenaline)</td><td>Insulin (HIET) – where cause attributed to excess B-blocker use and other meds (adren) ineffective</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 4 year old boy has been referred to the ED by his GP for a febrile illness of 6 days duration. The GP is worried about possible Kawasaki disease.","parts":[{"id":"a","label":"Part A","prompt":"List 5 examination features that would support the diagnosis of Kawasaki disease.\n(5 marks) 1) 2) 3) 4) 5)"},{"id":"b","label":"Part B","prompt":"List 3 differential diagnoses that can have a similar presentation to Kawasaki disease. For each, state a discriminatory finding on assessment (history, examination or investigation) that would support the diagnosis. (3 marks) 1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 2 key treatment measures for suspected Kawasaki disease. (2 marks)\n1) 2)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Cervical lymphadenopathy</div><div class=\"answer-line\">Non-purulent conjunctivitis</div><div class=\"answer-line\">Strawberry tongue</div><div class=\"answer-line\">Erythema Marginatum</div><div class=\"answer-line\">Painful erythema +/- oedema of hands and feet</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Group A Strep ie tonsillitis, scarlet fever, acute rheumatic fever</td><td>EBV, CMV</td></tr><tr><td>Sepsis</td><td>Toxic Shock (staph or strep)</td></tr><tr><td>SJS</td><td>Drug Reaction</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV Immunoglobulin</div><div class=\"answer-line\">High-dose aspirin</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 70 year old man has been brought to the ED with a 2 day history of progressive rash.\nA clinical photo is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of the rash from the photograph. (4 marks)\n1) 2) 3) 4) You are concerned about the possibility of Stevens-Johnson syndrome."},{"id":"b","label":"Part B","prompt":"List 3 findings from your further examination of this patient that would be consistent with Stevens-Johnson syndrome. (3 marks) 1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 2 differential diagnoses for this presentation. (2 marks)\n1) 2)"},{"id":"d","label":"Part D","prompt":"List 3 potential complications of Stevens-Johnson syndrome that can cause serious\nmorbidity. (3 marks) 1) 2) 3)"}],"propPages":["asset:imgfa1617f4a43178e214"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Macular rash to trunk and upper limb</div><div class=\"answer-line\">Areas of confluence</div><div class=\"answer-line\">Epidermal loss with blistering</div><div class=\"answer-line\">Discrete lesions of different sizes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Involvement of mucosal surfaces</div><div class=\"answer-line\">Marked pain</div><div class=\"answer-line\">Nikolsky sign +ve</div><div class=\"answer-line\">Degree of BSA involved in blistering (&lt;10%)</div><div class=\"answer-line\">Others…</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Staph scalded skin/toxic shock Sx</div><div class=\"answer-line\">Erythema multiforme</div><div class=\"answer-line\">Bullous SLE</div><div class=\"answer-line\">Paraneoplastic pemphigus</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Secondary infection</div><div class=\"answer-line\">Hypovolaemia from fluid losses</div><div class=\"answer-line\">ARDS</div><div class=\"answer-line\">GIT ulceration and perforation</div><div class=\"answer-line\">Others</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 43 year old woman has presented to hospital with diplopia.\nShe has been seen by a resident who thinks she has a third cranial nerve palsy.","parts":[{"id":"a","label":"Part A","prompt":"List 3 examination findings that would be consistent with a third cranial nerve palsy.\n(3 marks) 1) 2) 3) She has an isolated third cranial nerve palsy."},{"id":"b","label":"Part B","prompt":"In the table below, list 4 potential causes and for each, state an investigative finding that would confirm the diagnosis. (8 marks) Potential cause Investigative finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Down and out eye position</div><div class=\"answer-line\">Ptosis</div><div class=\"answer-line\">Mydriasis (in ‘surgical’ thirds)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Compression from PComm aneurysm – CTA demonstrating aneurysm</td><td>Demyelination – plaques on MRI</td></tr><tr><td>Tumour – SOL on CT</td><td>Cavernous sinus thrombosis – flow deficit on venous phase CT Head</td></tr><tr><td>Stroke – MRI</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 17 year old boy has presented with a painful, swollen right thigh after minor trauma.\nHe has a history of Haemophilia A. On initial assessment, he has a large intramuscular haematoma in the anterior compartment of his thigh.","parts":[{"id":"a","label":"Part A","prompt":"State 4 features of your history relevant to his haemophilia. Include the relevance of each feature. (4 marks) 1) 2) 3) 4) You are considering whether the patient might have compartment syndrome."},{"id":"b","label":"Part B","prompt":"List 4 examination findings that would be consistent with compartment syndrome.\n(4 marks) 1) 2) 3) 4) He does not have signs of compartment syndrome although he does have a large intramuscular haematoma of his quadriceps femoris."},{"id":"c","label":"Part C","prompt":"State 4 components of your management of this patient. (4 marks)\n1) 2) 3) 4)\nPAH 2021.2 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Home management plan – has patient already administered factor replacement for this episode –</div><div class=\"answer-line\">guides ongoing factor replacement</div><div class=\"answer-line\">Is patient on prophylaxis – guides ongoing factor replacement</div><div class=\"answer-line\">Severity of haemophilia – guides urgency of factor replacement, predicted clinical course</div><div class=\"answer-line\">Patient weight – for factor replacement dosing</div><div class=\"answer-line\">Does patient have central access – preferred/recommended IV access for patient</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">No distal pulses</div><div class=\"answer-line\">Pain with passive flexion of knee</div><div class=\"answer-line\">Parasthesia over anterior compartment</div><div class=\"answer-line\">Severe pain out of proportion to clinical situation</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Discussion with haematologist</div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Rest, ice, compression, elevation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 35 year old man has presented after falling 2 metres off a ladder while repairing a fence. He is complaining of severe neck pain. A slice from a CT of his cervical spine is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 key findings from the CT image. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"State 5 key features of your examination pertaining to the injury shown. Include the\nrelevance of each. (5 marks) 1) 2) 3) 4) 5)"},{"id":"c","label":"Part C","prompt":"Complete the table regarding 3 incomplete spinal cord syndromes. (3 marks) Syndrome Associated neurological deficit Anterior cord syndrome Central cord syndrome Brown-Sequard syndrome"}],"propPages":["asset:imgd26bc63511ad7186d3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Anterolisthesis &gt;50% C6/C7 or bilateral facet dislocation C6/C7</div><div class=\"answer-line\">Fracture of C7 vertebral body</div><div class=\"answer-line\">Retropulsion of C7 into spinal canal</div><div class=\"answer-line\">Widened interspinous distance C6/C7</div><div class=\"answer-line\">Pre-vertebral soft tissue swelling</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Breathing</strong> – spinal cord injury involving diaphragm, need for respiratory support</div><div class=\"answer-line\"><strong>Haemodynamics –</strong> neurogenic shock, need for vasopressors</div><div class=\"answer-line\">Motor assessment – assess for presence and level of spinal cord injury</div><div class=\"answer-line\">Sensory assessment – assess for level</div><div class=\"answer-line\">Reflexes – lost distally in complete spinal cord injury</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Anterior cord syndrome – loss of motor, pain, temperature with preserved dorsal column</div><div class=\"answer-line\">(proprioception/vibratory sense)</div><div class=\"answer-line\">Central cord syndrome – motor deficit worse in upper limbs than lower limbs</div><div class=\"answer-line\">Brown-Sequard syndrome – ipsilateral motor loss, contralateral pain and temperature loss</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 3 year old girl has been brought to the ED by her mother. She has a loud stridor.","parts":[{"id":"a","label":"Part A","prompt":"List 4 possible causes apart from croup. For each, state a key discriminatory feature of\nyour history, examination or investigation. (8 marks) Cause Key feature of history, examination or investigation Your assessment is consistent with severe croup. The patient’s vital signs are: Mildly agitated Pulse 160 /min\n\nBP\n100/60 mmHg\n\nRR\n/min O2 sats 98% room air"},{"id":"b","label":"Part B","prompt":"State 3 components of your management. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 3 examination features that would indicate impending respiratory arrest. (3 marks)\n1) 2) 3) Despite your initial management, the patient has deteriorated and you are preparing to intubate."},{"id":"d","label":"Part D","prompt":"State 4 features of your intubation that will vary from a standard rapid sequence\ninduction. Explain your rationale. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Foreign body aspiration – acute choking episode, post food/toys in mouth, FB on xray</td><td>Epiglottitis – febrile sick child, drooling, thumb sign on lateral neck xray</td></tr><tr><td>Peritonsillar abscess – enlarged inflamed tonsils with adjacent abscess on view</td><td>Retropharyngeal abscess – neck stiffness and hyperextension, hx of penetrating trauma (e.g. fall</td></tr><tr><td>with stick in mouth)</td><td>Bacterial tracheitis – recent URTI with sudden deterioration</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Steroids – dexamethasone 0.6mg/kg (IM/IV/PO)</div><div class=\"answer-line\">Observation</div><div class=\"answer-line\">Parental reassurance</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Marked dec respiratory rate</div><div class=\"answer-line\">Decreased conscious state</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pre-oxygenation and induction in seated position – avoid further distress/airway obstruction</div><div class=\"answer-line\">Bag through apnoeic period – prevent hypoxia</div><div class=\"answer-line\">Smaller size ETT – predicting airway oedema</div><div class=\"answer-line\">Video laryngoscopy – maximise view</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 38 year old man has been bought to the ED with right knee pain.\nHe jumped from the tray of a ute and landed heavily on his right foot.","parts":[{"id":"b","label":"Part B","prompt":"List 2 abnormalities on the x-rays. (2 marks)\n1) 2)"},{"id":"c","label":"Part C","prompt":"List 2 structures that are commonly injured in association with this injury pattern.\n(2 marks) 1) 2)"},{"id":"d","label":"Part D","prompt":"State 3 components of your management of this injury. (3 marks)\n1) 2) 3) A member of your nursing staff has suffered a needlestick injury while attempting IV cannulation on the patient."},{"id":"e","label":"Part E","prompt":"State 4 components of your history that are relevant to your management of this\nsituation. Provide explanation for each. (4 marks) 1) 2) 3) 4)"}],"propPages":["asset:img5e091c468c74d7f262","asset:img2343a9756c6f3ec7c0"],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["rays of his right knee are provided below."],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lipohaemarthrosis</div><div class=\"answer-line\">Lateral tibial plateau fracture – schatzker I or II</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Lateral menisci</div><div class=\"answer-line\">Medial collateral ligament</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Hinged knee brace</div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Orthopaedic follow-up</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Was the skin breached and associated with visible bleeding</td><td>Was the needle contaminated with source blood</td></tr><tr><td>Was area immediately washed with soap and water</td><td>Does staff member have record of antiHBs &gt;10</td></tr><tr><td>Is source known or likely to be HCV or HIV positive</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"An 85 year old man has been found lying on the floor of his home.\nHe has a history of ischaemic heart disease, hypertension, and type 2 diabetes mellitus. His electrolyte panel is provided below.\n\nNa\n143 mmol/L (135 - 145)\n\nK\n5.3 mmol/L (3.5 - 5.1)\n\nCl\n106 mmol/L (100 - 110)\n\nHCO3\nmmol/L (22 - 32)\n\nUrea\n38.9 mmol/L (2.1 - 7.1) Creat 351 umol/L (46 - 90)\n\nBSL\nmmol/L (3.0 - 7.8) CK 145 U/L (34 - 145)","parts":[{"id":"a","label":"Part A","prompt":"State the most likely diagnosis, based on the results provided. (1 mark)"},{"id":"b","label":"Part B","prompt":"State 4 additional problems evident from the results provided. Provide an explanation for\nthe cause of each. (8 marks) Problem Cause On assessment, the patient has cellulitis of his left foot.\nHis vital signs are;\n\nGCS\nE3 V4 M6\n\nHR\n140 /min\n\nBP\n105/70 mmHg\n\nTemp\n38.4 degrees"},{"id":"c","label":"Part C","prompt":"State 4 components of your management. (4 marks)\n1) 2) 3) 4)"},{"id":"d","label":"Part D","prompt":"List 5 additional investigations you might perform. Provide justification for each.\n(5 marks) Investigation Justification"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hyperosmolar hyperglycaemic state</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hyperkalaemia – dec renal excretion, acidosis</div><div class=\"answer-line\">HAGMA – renal failure, also accept ketones, lactate</div><div class=\"answer-line\">Renal impairment – increased urea/creatinine ratio indicates pre-renal failure from dehydration</div><div class=\"answer-line\">Dilutional normonatraemia – corrected sodium is 158 – dehydration</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV insulin infusion</div><div class=\"answer-line\">IV fluid bolus</div><div class=\"answer-line\">IV antibiotics</div><div class=\"answer-line\">IV potassium replacement</div><div class=\"answer-line\">VTE prophylaxis</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>ECG – history of ischaemic heart disease – exclude MI as a precipitant for HHS</td><td>CT head – reduced GCS, found on floor at home – exclude traumatic intracranial bleed</td></tr><tr><td>CXR – reduced GCS – exclude aspiration</td><td>Urine m/c/s – acute renal impairment + fever – exclude UTI as cause</td></tr><tr><td>LFTs – renal impairment + reduced GCS – assess degree of end organ failure</td><td>Lactate</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 5 month old boy has presented to the triage desk with cyanosis. His mother states he has a heart defect and is awaiting further surgery but is “more blue and upset” than usual. The patient’s chart reveals that he has Tetralogy of Fallot and is soon to undergo definitive repair.","parts":[{"id":"a","label":"Part A","prompt":"List the 4 cardiac abnormalities that make up Tetralogy of Fallot. (4 marks)\n1) 2) 3) 4) Your initial assessment is of a “Tet spell”."},{"id":"b","label":"Part B","prompt":"List 3 conditions that may trigger a Tet spell. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 4 components of your initial management of this patient. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">VSD</div><div class=\"answer-line\">Pulmonary stenosis</div><div class=\"answer-line\">Overriding aorta</div><div class=\"answer-line\">RV hypertrophy</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Sepsis or infection</div><div class=\"answer-line\">Pain response to an injury</div><div class=\"answer-line\">Dehydration</div><div class=\"answer-line\">Overexertion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Knee to chest position</div><div class=\"answer-line\">High flow oxygen via NRBM</div><div class=\"answer-line\">Morphine 0.2mg/kg IM</div><div class=\"answer-line\">Avoid exacerbating distress</div><div class=\"answer-line\">Correct underlying cause</div><div class=\"answer-line\">IV fluids 10ml/kg</div><div class=\"answer-line\">Sodium bicarb 2-3mmol/kg IV</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"An 89 year old nursing home patient has presented to the ED with abdominal pain and distension. An abdominal x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State your diagnosis with 3 supporting radiographic abnormalities. (4 marks)\nDiagnosis Supporting abnormalities 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 possible treatment options for this problem. (3 marks)\n1) 2) 3)"},{"id":"c","label":"Part C","prompt":"List 5 considerations when determining the appropriate treatment option. Include the\nrelevance of each. (5 marks) 1) 2) 3) 4) 5)"}],"propPages":["asset:imgcf38ac8b5ad60239a4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Volvulus - ?prob caecal – I think we should accept sigmoid as well</div><div class=\"answer-line\">Distended large bowel loops</div><div class=\"answer-line\">Coffee bean sign</div><div class=\"answer-line\">No air in rectum</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Decompression with flexi sig/rectal tube</div><div class=\"answer-line\">Surgical resection/colectomy</div><div class=\"answer-line\">Percutaneous endoscopic colectomy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Co-morbidities – medical fitness for surgical intervention</div><div class=\"answer-line\">Anticoagulation – need for reversal prior to procedure</div><div class=\"answer-line\">Patient preference – statement of choices</div><div class=\"answer-line\">Quality of life – frailty, ADLs</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 6 year old girl has presented with a painful left arm following a fall from the monkey bars at school. A photograph of her arm is shown below.","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely diagnosis? (2 marks)"},{"id":"b","label":"Part B","prompt":"List 5 potential acute complications of this injury and state how you would assess for each. (5 marks) 1) 2) 3) 4) 5) There are no apparent acute complications.\nThe child weighs 20kg."},{"id":"c","label":"Part C","prompt":"State 2 options for analgesia including route and doses. (2 marks)\n1) 2)"},{"id":"d","label":"Part D","prompt":"State 2 other components of your management. (2 marks)\n1) 2)"}],"propPages":["asset:img7d7c8e3076ef629bdb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Supracondylar fracture</div><div class=\"answer-line\">Closed, grade III (or high grade)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Anterior interosseous branch median nerve – cannot make OK sign</td><td>Radial nerve – wrist drop</td></tr><tr><td>Ulnar nerve – cannot adduct/abduct fingers</td><td>Radial artery transection – loss of radial pulse</td></tr><tr><td>Compartment syndrome – severe forearm pain with passive extension fingers</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Fentanyl IN 1.5mcg/kg</div><div class=\"answer-line\">Morphine IV 0.2mg/kg</div><div class=\"answer-line\">Oxycodone PO 0.2mg/kg</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">POP long arm backslab</div><div class=\"answer-line\">Orthopaedic referral for definitive management/OT</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 45 year old man has presented to the ED with haematuria.","parts":[{"id":"a","label":"Part A","prompt":"In the table below, list 6 possible causes. For each, state a discriminatory feature of your assessment (history, examination, investigation) in keeping with the diagnosis. (12 marks) Cause Discriminatory assessment feature"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Ureteric calculi – sudden onset, colicky loin to groin pain</td><td>Renal cell carcinoma – painless haematuria; positive urine cytology</td></tr><tr><td>Haemorrhagic cystitis – dysuria, increased urinary freq; positive urine culture</td><td>Glomerulonephritis – preceding strep throat, known autoimmune disease</td></tr><tr><td>BPH – nocturia, hesitancy, weak stream; smooth enlarged nontender prostate on DRE</td><td>Urethral trauma – recent procedure/cystoscopy/catheter insertion/FB insertion</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"An 85 year old man has presented with a painful and pulseless right lower leg. You suspect an ischaemic limb.","parts":[{"id":"a","label":"Part A","prompt":"List 3 features of your history or examination that would indicate an embolic occlusion.\n(3 marks) 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 features of your history or examination that would indicate a thrombotic occlusion. (3 marks) 1) 2) 3)"},{"id":"c","label":"Part C","prompt":"State two findings from bedside clinical investigations that would suggest arterial\n• cclusion. (2 marks)\n1) 2) CT angiogram has demonstrated an occlusion of the right femoral artery."},{"id":"d","label":"Part D","prompt":"State 3 components of your management. (3 marks)\n1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">No history of claudication</div><div class=\"answer-line\">Acute onset of symptoms</div><div class=\"answer-line\">Paroxysmal AF</div><div class=\"answer-line\">Normal contralateral limb on examination</div><div class=\"answer-line\">Known AAA</div><div class=\"answer-line\">No collateral circulation on imaging</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">History of claudication</div><div class=\"answer-line\">History of peripheral vascular disease</div><div class=\"answer-line\">Gradual onset of symptoms</div><div class=\"answer-line\">Signs of arterial disease bilaterally (shiny skin, hyperpigmentation, hair loss, ulcers)</div><div class=\"answer-line\">Widespread disease with collateral circulation on imaging</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">ABI &lt;0.5</div><div class=\"answer-line\">No pulses on doppler US</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Heparin infusion</div><div class=\"answer-line\">Analgesia</div><div class=\"answer-line\">Vascular referral</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
